// throws.cpp -- see modbase/throws.h.

#include "modbase/throws.h"

// Generated by sweet-dx from hooks/throws.hks.
namespace ModBase { namespace throws { int canThrow_orig(void* player); } }
namespace ModBase { namespace throws { int startThrow_orig(void* player); } }
namespace ModBase { namespace throws { int throwExecute_orig(void* player); } }
namespace ModBase { namespace throws { int createFireBall_orig(void* player, int spin); } }

// The game's per-player projectile counts (symbols/player/player.sym): a
// pointer to a block in which player n's fireballs are the s32 at
// +0x68 + 8 * n and its iceballs the one at +0x88 + 8 * n.
namespace ModBase { namespace throws { extern u8* projectileCounts; } }

namespace {

ModBase::throws::Gate sGates[ModBase::throws::cMaxGates];
ModBase::throws::Handler sHandlers[ModBase::throws::cMaxHandlers];
u32 sNumGates;
u32 sNumHandlers;

bool allowed(void* player)
{
    for (u32 i = 0; i < sNumGates; i++)
        if (!sGates[i](player))
            return false;
    return true;
}

// The throw checks' limits: a throw starts while fewer than 2 fireballs (Fire)
// or at most 1 iceball (Penguin, Ice) are out.
constexpr s32 cMaxFireballs = 2;
constexpr s32 cMaxIceballs  = 2;

// The Throw state (0x60CC4D6C) keeps its phase at +0x26D4: 0 until the
// projectile leaves the hand (frame 4), then 1, in which the button throws again.
constexpr u32 cThrowPhase      = 0x26D4;
constexpr u32 cThrowPhase_Done = 1;

} // namespace

// The game starts a throw from three places, each with the same test (the
// button at +0x2B0 pressed and the mode's projectiles under the limit):
//
//   Player::canThrow  0x607AA954  asked by the swim, carried and other states
//                                 that throw inside their own state
//   startThrow        0x607AAA00  the ordinary throw (standing, walking,
//                                 jumping; from 0x607965CC): its own copy of
//                                 the test, then the Throw state 0x60CC4D6C,
//                                 whose begin (0x607AAF18) plays animation 33
//   Throw execute     0x607AAF80  phase 1: its own copy again, then animation
//                                 33 once more -- a throw right after a throw
//
// The gates are asked in all three, before any animation starts.

// Player::canThrow (0x607AA954): 1 lets the asking state throw.
namespace ModBase { namespace throws { int canThrow(void* player); } }
int ModBase::throws::canThrow(void* player)
{
    int r = ModBase::throws::canThrow_orig(player);
    if (r != 1)
        return r;
    return allowed(player) ? r : 0;
}

// The ordinary throw (0x607AAA00): 1 when it moved the player to the Throw
// state, 0 when it did nothing -- as it returns when the test fails.
namespace ModBase { namespace throws { int startThrow(void* player); } }
int ModBase::throws::startThrow(void* player)
{
    if (!allowed(player))
        return 0;
    return ModBase::throws::startThrow_orig(player);
}

// The Throw state's execute (0x607AAF80). In phase 1 a forbidden throw has to
// fail the state's own test while the rest of the state (turning back to
// walking or falling as the animation ends) runs as usual, so the player's
// counts are held at the limit for that one call.
namespace ModBase { namespace throws { int throwExecute(void* player); } }
int ModBase::throws::throwExecute(void* player)
{
    if (*(u32*)((u8*)player + cThrowPhase) != cThrowPhase_Done || allowed(player)
        || !ModBase::throws::projectileCounts)
        return ModBase::throws::throwExecute_orig(player);

    u8 n = *((u8*)player + 0x54);       // as the game reads it: player no., 0 if not 0-3
    s32* fire = (s32*)(ModBase::throws::projectileCounts + 0x68 + 8 * (n < 4 ? n : 0));
    s32* ice  = (s32*)((u8*)fire + 0x20);
    s32 addFire = *fire < cMaxFireballs ? cMaxFireballs - *fire : 0;
    s32 addIce  = *ice < cMaxIceballs ? cMaxIceballs - *ice : 0;
    *fire += addFire;
    *ice  += addIce;
    int r = ModBase::throws::throwExecute_orig(player);
    *fire -= addFire;
    *ice  -= addIce;
    return r;
}

// Player::createFireBall (0x607AABA0): (player, spin). Also reached without
// any of the above (the spin-jump throw, 0x607AB2C8), so the gates apply here too.
namespace ModBase { namespace throws { int createFireBall(void* player, int spin); } }
int ModBase::throws::createFireBall(void* player, int spin)
{
    if (!allowed(player))
        return 0;
    for (u32 i = 0; i < sNumHandlers; i++) {
        int result = 0;
        if (sHandlers[i](player, spin, &result))
            return result;
    }
    return ModBase::throws::createFireBall_orig(player, spin);
}

namespace ModBase {
namespace throws {

bool addGate(Gate gate)
{
    if (!gate || sNumGates >= cMaxGates)
        return false;
    sGates[sNumGates++] = gate;
    return true;
}

bool addHandler(Handler handler)
{
    if (!handler || sNumHandlers >= cMaxHandlers)
        return false;
    sHandlers[sNumHandlers++] = handler;
    return true;
}

} // namespace throws
} // namespace ModBase
